# Observed annual yields by cropping system.
# Solid lines connect adjacent harvest years; dotted lines span unobserved years.
# Reads the annual treatment means generated by the main analysis pipeline.

if (!requireNamespace("ggplot2", quietly = TRUE)) {
  stop("ggplot2 is required. Install it with install.packages('ggplot2').")
}

OUTPUT_ROOT <- file.path(getwd(), "FST_V9_FINAL_ANALYSIS_outputs")
INPUT_CSV <- file.path(OUTPUT_ROOT, "tables", "S1_05_composite_annual_means_PRIMARY.csv")
FIGURE_DIR <- file.path(OUTPUT_ROOT, "figures")
if (!file.exists(INPUT_CSV)) {
  stop("Annual treatment means file not found: ", INPUT_CSV,
       "\nOUTPUT_ROOT should point to the analysis output directory.")
}
if (!dir.exists(FIGURE_DIR)) dir.create(FIGURE_DIR, recursive = TRUE)

dat <- read.csv(INPUT_CSV, stringsAsFactors = FALSE)
need <- c("Crop", "Year", "System", "Yield_Mg_ha")
if (!all(need %in% names(dat))) stop("Missing required columns in ", INPUT_CSV)
dat <- dat[!is.na(dat$Year) & is.finite(dat$Yield_Mg_ha), , drop = FALSE]
dat$Year <- as.integer(dat$Year)
dat$Crop <- factor(dat$Crop, levels = c("corn", "soybean", "wheat"),
                   labels = c("Corn", "Soybean", "Wheat"))
dat$System <- factor(dat$System, levels = c("CNV", "LEG", "MNR"))
dat <- dat[order(dat$Crop, dat$System, dat$Year), , drop = FALSE]
if (any(duplicated(dat[, c("Crop", "System", "Year")]))) {
  stop("Expected one observed mean per crop, system and year.")
}

# Connect observed endpoints; segment type reflects the calendar-year gap.
by_series <- split(dat, interaction(dat$Crop, dat$System, drop = TRUE))
segments <- do.call(rbind, lapply(by_series, function(z) {
  z <- z[order(z$Year), , drop = FALSE]
  n <- nrow(z)
  if (n < 2L) return(NULL)
  data.frame(
    Crop = z$Crop[-n],
    System = z$System[-n],
    Year_start = z$Year[-n], Year_end = z$Year[-1L],
    Yield_start = z$Yield_Mg_ha[-n], Yield_end = z$Yield_Mg_ha[-1L],
    gap_years = z$Year[-1L] - z$Year[-n] - 1L
  )
}))
solid <- segments[segments$gap_years == 0L, , drop = FALSE]
dotted <- segments[segments$gap_years > 0L, , drop = FALSE]

library(ggplot2)
colors <- c(CNV = "#4977A5", LEG = "#E49A5A", MNR = "#298A76")

p <- ggplot() +
  geom_vline(xintercept = 2008, color = "#80909E",
             linetype = "dashed", linewidth = 0.45) +
  geom_segment(data = solid,
               aes(x = Year_start, y = Yield_start,
                   xend = Year_end, yend = Yield_end, color = System),
               linewidth = 0.72, lineend = "round") +
  geom_segment(data = dotted,
               aes(x = Year_start, y = Yield_start,
                   xend = Year_end, yend = Yield_end, color = System),
               linetype = "dotted", linewidth = 0.72, alpha = 0.76,
               lineend = "round") +
  geom_point(data = dat, aes(x = Year, y = Yield_Mg_ha, color = System),
             size = 1.95) +
  facet_grid(Crop ~ ., scales = "free_y") +
  scale_color_manual(values = colors, breaks = c("CNV", "LEG", "MNR")) +
  scale_x_continuous(breaks = seq(1981, 2021, by = 5),
                     limits = c(1980.5, 2024.8), expand = expansion(mult = 0)) +
  labs(
    title = "Annual grain yields by cropping system, 1981–2024",
    subtitle = "Observed annual means · FT before 2008; equal FT/RT after 2008",
    x = "Calendar year", y = "Grain yield (Mg/ha)", color = NULL,
    caption = paste(
      "Solid lines join consecutive observed years; dotted lines bridge unobserved years.",
      "Only points represent observed yields; dashed vertical line marks 2008."
    )
  ) +
  theme_minimal(base_size = 11) +
  theme(
    plot.title = element_text(face = "bold", size = 13, hjust = 0),
    plot.subtitle = element_text(size = 10, color = "#546477"),
    plot.title.position = "plot",
    plot.caption = element_text(hjust = 0, color = "#64748B", size = 8.5),
    plot.caption.position = "plot",
    panel.grid.minor = element_blank(),
    panel.grid.major.x = element_blank(),
    panel.grid.major.y = element_line(color = "#EBEFF3", linewidth = 0.35),
    panel.spacing.y = grid::unit(0.18, "cm"),
    panel.border = element_rect(color = "#222222", linewidth = 0.5, fill = NA),
    strip.background = element_rect(fill = "white", color = "#222222", linewidth = 0.5),
    strip.text.y.right = element_text(face = "bold", angle = 270, size = 10.5),
    legend.position = "bottom", legend.direction = "horizontal",
    legend.key = element_blank(), legend.title = element_blank(),
    axis.title = element_text(size = 10)
  )

# This plot is saved separately from the model-trajectory figure.
png_file <- file.path(FIGURE_DIR, "MAIN_FIGURE_1_observed_yields_dotted_gaps.png")
tiff_file <- file.path(FIGURE_DIR, "MAIN_FIGURE_1_observed_yields_dotted_gaps.tiff")
ggsave(png_file, p, width = 10.3, height = 7.6, dpi = 350, bg = "white")
ggsave(tiff_file, p, width = 10.3, height = 7.6, dpi = 600,
       compression = "lzw", bg = "white")
print(p)
message("Created the figure only:\n  ", png_file, "\n  ", tiff_file,
        "\nSolid segments: ", nrow(solid),
        " | Dotted gap segments: ", nrow(dotted))
